package si.konferenca.registration.acceptance;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;
import java.util.stream.Stream;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;
import org.junit.jupiter.params.provider.ValueSource;
import tools.jackson.databind.node.ObjectNode;

/** US-002 student registration, through the REST API. */
class StudentRegistrationAcceptanceTest extends AcceptanceTestBase {

  private static final List<String> REQUIRED =
      List.of("firstName", "lastName", "email", "studyInstitution", "studyProgramme", "studentId");

  static Stream<Arguments> requiredFieldVariants() {
    return REQUIRED.stream()
        .flatMap(
            f -> Stream.of(Arguments.of(f, "missing"), Arguments.of(f, ""), Arguments.of(f, "  ")));
  }

  @Test
  @DisplayName("AC-002-01 valid student submission is accepted with a new registration id")
  void ac00201ValidStudentSubmissionAccepted() {
    String id = assertAccepted(api.postRegistration(Submissions.validStudent()));

    assertThat(
            AcceptanceEnvironment.query(
                "SELECT type FROM registration WHERE id = ?::uuid", id))
        .singleElement()
        .satisfies(row -> assertThat(row).containsEntry("type", "STUDENT"));
  }

  @ParameterizedTest(name = "AC-002-02 {0} = [{1}] is rejected")
  @MethodSource("requiredFieldVariants")
  @DisplayName("AC-002-02 missing, empty or whitespace required student field is rejected")
  void ac00202RequiredFieldRejected(String field, String value) {
    ObjectNode body = Submissions.validStudent();
    if ("missing".equals(value)) {
      body.remove(field);
    } else {
      body.put(field, value);
    }

    assertRejected(api.postRegistration(body), field);
  }

  @ParameterizedTest(name = "AC-002-03 email [{0}] is rejected")
  @ValueSource(strings = {"luka", "luka@", "@student.example.si", "luka kranjc@x.si", "luka@x"})
  @DisplayName("AC-002-03 invalid email format is rejected")
  void ac00203InvalidEmailRejected(String email) {
    ObjectNode body = Submissions.validStudent();
    body.put("email", email);

    assertRejected(api.postRegistration(body), "email");
  }

  @Test
  @DisplayName("AC-002-04 active option not available to students is rejected")
  void ac00204OptionNotForStudentsRejected() {
    ObjectNode body = Submissions.validStudent();
    body.putArray("optionIds").add("ws-a").add("ws-ext");

    assertRejected(api.postRegistration(body), "options");
  }

  @ParameterizedTest(name = "AC-002-05 privacy consent {0} is rejected")
  @ValueSource(strings = {"false", "absent"})
  @DisplayName("AC-002-05 mandatory consent not given is rejected")
  void ac00205MandatoryConsentMissingRejected(String variant) {
    ObjectNode body = Submissions.validStudent();
    if ("false".equals(variant)) {
      body.putObject("consents").put("privacy", false);
    } else {
      body.putObject("consents");
    }

    assertRejected(api.postRegistration(body), "consents.privacy");
  }

  @ParameterizedTest(name = "AC-002-06 reCAPTCHA token {0} is rejected")
  @ValueSource(strings = {"missing", "rejected-by-verifier"})
  @DisplayName("AC-002-06 missing or rejected reCAPTCHA token is rejected and nothing stored")
  void ac00206CaptchaRejected(String variant) {
    ObjectNode body = Submissions.validStudent();
    if ("missing".equals(variant)) {
      body.remove("recaptchaToken");
    } else {
      body.put("recaptchaToken", "not-a-valid-token");
    }

    assertRejected(api.postRegistration(body), "recaptchaToken");
  }
}

import { screen, within } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import { chooseType, jsonResponse, renderPage, stubBackend } from "./support";

describe("US-002 student form", () => {
  it("AC-002-07 shows exactly the student fields, only student options grouped by category and unchecked consents", async () => {
    stubBackend(() => jsonResponse(500, { message: "unused" }));
    await renderPage();

    chooseType("Student");

    for (const label of [
      "First name",
      "Last name",
      "Email",
      "Study institution",
      "Study programme",
      "Student ID",
    ]) {
      expect(screen.getByLabelText(label)).toBeInTheDocument();
    }
    expect(screen.queryByLabelText("Organization / institution")).not.toBeInTheDocument();
    expect(screen.getAllByRole("textbox")).toHaveLength(6);

    const groups: Record<string, string[]> = {
      Workshops: ["Workshop A"],
      Events: ["Evening event"],
      Meals: ["Lunch"],
      "Other activities": ["City tour", "Student meetup"],
    };
    for (const [legend, names] of Object.entries(groups)) {
      const group = screen.getByRole("group", { name: legend });
      expect(within(group).getAllByRole("checkbox")).toHaveLength(names.length);
      for (const name of names) {
        expect(within(group).getByRole("checkbox", { name })).toBeInTheDocument();
      }
    }
    expect(
      screen.queryByRole("checkbox", { name: "Workshop for externals" }),
    ).not.toBeInTheDocument();

    const consents = within(screen.getByRole("group", { name: "Consents" })).getAllByRole(
      "checkbox",
    );
    expect(consents).toHaveLength(2);
    for (const box of consents) {
      expect(box).not.toBeChecked();
    }
  });
});

import { expect, test } from "@playwright/test";
import { awaitMessages, confirmConsentAndCaptcha, fillFields, literal, sql, unique } from "./support";

test("E2E-02 student registers (AC-002-01, AC-002-07, AC-004-01)", async ({ page }) => {
  const run = unique();
  const firstName = "Luka";
  const lastName = `Student${run}`;
  const email = `luka.${run}@e2e.example`;

  await page.goto("/");
  await page.getByRole("radio", { name: "Student" }).check();

  // Only the student fields and the options available to students (shipped configuration)
  await expect(page.getByLabel("Organization / institution", { exact: true })).toHaveCount(0);
  await expect(page.getByRole("checkbox", { name: "Workshop: Industry partnerships" })).toHaveCount(0);
  await expect(page.getByRole("checkbox", { name: "Gala dinner" })).toHaveCount(0);
  await expect(page.getByRole("checkbox", { name: "Student mentoring session" })).toBeVisible();

  await fillFields(page, {
    "First name": firstName,
    "Last name": lastName,
    Email: email,
    "Study institution": "Univerza v Mariboru",
    "Study programme": "Informatika",
    "Student ID": `S${run}`,
  });
  await page.getByRole("checkbox", { name: "Workshop: Cloud-native architecture" }).check();
  await page.getByRole("checkbox", { name: "Student mentoring session" }).check();
  await confirmConsentAndCaptcha(page);
  await page.getByRole("button", { name: "Register" }).click();

  await expect(page.getByRole("heading", { level: 2, name: "Registration received" })).toBeVisible();
  await expect(page.getByText(`Thank you, ${firstName} ${lastName}.`)).toBeVisible();
  const selected = page.getByRole("list", { name: "Selected options" });
  await expect(selected.getByText("Student mentoring session", { exact: true })).toBeVisible();

  const rows = sql(
    `SELECT type, study_institution, study_programme, student_id, organization FROM registration WHERE email = ${literal(email)}`,
  );
  expect(rows).toEqual([["STUDENT", "Univerza v Mariboru", "Informatika", `S${run}`, ""]]);

  const messages = await awaitMessages(lastName, 2);
  expect(messages.filter((m) => m.To.some((t) => t.Address === email))).toHaveLength(1);
  expect(messages.filter((m) => m.Subject.startsWith("New registration")).length).toBeGreaterThanOrEqual(1);
});

