  interface Window {
    grecaptcha?: Grecaptcha;
  }
}

interface CaptchaProps {
  mode: "test" | "recaptcha";
  siteKey: string | null;
  token: string | null;
  onToken: (token: string | null) => void;
  /** Incremented after a rejected submission to reset the widget. */
  resetCount: number;
  describedBy?: string;
}

function loadScript(): Promise<Grecaptcha> {
  return new Promise((resolve, reject) => {
    if (window.grecaptcha) {
      window.grecaptcha.ready(() => resolve(window.grecaptcha as Grecaptcha));
      return;
    }
    const script = document.createElement("script");
    script.src = SCRIPT_URL;
    script.async = true;
    script.onload = () => {
      const api = window.grecaptcha;
      if (api) {
        api.ready(() => resolve(api));
      } else {
        reject(new Error("reCAPTCHA did not load"));
      }
    };
    script.onerror = () => reject(new Error("reCAPTCHA did not load"));
    document.head.appendChild(script);
  });
}

/** Anti-automation control: Google reCAPTCHA v2, or a checkbox in test mode (SR-01, SR-02). */
export function Captcha(props: CaptchaProps) {
  const { mode, siteKey, token, onToken, resetCount, describedBy } = props;
  const container = useRef<HTMLDivElement>(null);
  const widget = useRef<{ api: Grecaptcha; id: number } | null>(null);
  const tokenHandler = useRef(onToken);
  tokenHandler.current = onToken;

  useEffect(() => {
    if (mode !== "recaptcha" || !siteKey || !container.current) return;
    const element = container.current;
    let cancelled = false;
    loadScript()
      .then((api) => {
        if (cancelled || element.childElementCount > 0) return;
        const id = api.render(element, {
          sitekey: siteKey,
          callback: (value) => tokenHandler.current(value),
          "expired-callback": () => tokenHandler.current(null),
        });
        widget.current = { api, id };
      })
      .catch(() => tokenHandler.current(null));
    return () => {
      cancelled = true;
    };
  }, [mode, siteKey]);

  useEffect(() => {
    if (resetCount > 0 && widget.current) {
      widget.current.api.reset(widget.current.id);
      tokenHandler.current(null);
    }
  }, [resetCount]);

  if (mode === "test") {
    return (
      <label className="checkbox">
        <input
          type="checkbox"
          checked={token === TEST_TOKEN}
          aria-invalid={describedBy ? true : undefined}
          aria-describedby={describedBy}
          onChange={(event) => onToken(event.target.checked ? TEST_TOKEN : null)}
        />
        I am not a robot (test mode)
      </label>
    );
  }
  return (
    <div
      ref={container}
      data-testid="recaptcha"
      aria-describedby={describedBy}
    />
  );
}

/** The id of the error element of a field (`ui-contract.md`, "Field errors"). */
export function errorId(field: string): string {
  return `error-${field}`;
}

/** An error rendered directly after its field or group. */
export function FieldErrorText({
  field,
  message,
}: {
  field: string;
  message?: string;
}) {
  if (!message) return null;
  return (
    <p id={errorId(field)} data-testid={errorId(field)} className="field-error">
      {message}
    </p>
  );
}

import type { FormOption, RegistrationType } from "../types";
import { CATEGORIES } from "../validation";
import { FieldErrorText, errorId } from "./FieldErrorText";

interface OptionGroupsProps {
  options: FormOption[];
  type: RegistrationType;
  selected: Set<string>;
  onToggle: (id: string) => void;
  error?: string;
}

/** Active options available to the type, one group per category (BR-04, OQ-01). */
export function OptionGroups(props: OptionGroupsProps) {
  const { options, type, selected, onToggle, error } = props;
  const available = options.filter((o) => o.availableTo.includes(type));
  return (
    <>
      <div
        data-testid="options"
        role="group"
        aria-label="Options"
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? errorId("options") : undefined}
      >
        {CATEGORIES.map(({ category, legend }) => {
          const inCategory = available.filter((o) => o.category === category);
          if (inCategory.length === 0) return null;
          return (
            <fieldset key={category}>
              <legend>{legend}</legend>
              {inCategory.map((option) => (
                <label key={option.id} className="checkbox">
                  <input
                    type="checkbox"
                    checked={selected.has(option.id)}
                    onChange={() => onToggle(option.id)}
                  />
                  {option.name}
                </label>
              ))}
            </fieldset>
          );
        })}
      </div>
      <FieldErrorText field="options" message={error} />
    </>
  );
}

import type { RegistrationAccepted } from "../types";

/** Shown only after the backend accepted the registration (BR-06, AC-004-01). */
export function Confirmation({
  registration,
}: {
  registration: RegistrationAccepted;
}) {
  return (
    <section>
      <h2>Registration received</h2>
      <p>
        Thank you, {registration.firstName} {registration.lastName}.
      </p>
      {registration.options.length > 0 ? (
        <ul aria-label="Selected options">
          {registration.options.map((option) => (
            <li key={option.id}>{option.name}</li>
          ))}
        </ul>
      ) : (
        <p>No options selected.</p>
      )}
    </section>
  );
}

