:root {
  font-family: system-ui, sans-serif;
  line-height: 1.5;
  color: #1f2328;
  background: #ffffff;
}

main {
  max-width: 40rem;
  margin: 0 auto;
  padding: 1rem;
}

fieldset {
  margin: 0 0 1rem;
  border: 1px solid #d0d7de;
  border-radius: 0.375rem;
}

.field {
  display: flex;
  flex-direction: column;
