    assertThat(validate(Map.of())).isEmpty();
  }

  @Test
  void validStudentSubmissionHasNoErrors() {
    Map<String, Object> v = new HashMap<>();
    v.put("type", "STUDENT");
    v.put("organization", null);
    v.put("studyInstitution", "Uni");
    v.put("studyProgramme", "CS");
    v.put("studentId", "1");
    assertThat(validate(v)).isEmpty();
  }

  @Test
  void unknownTypeIsReportedAndTypeFieldsAreNotChecked() {
    assertThat(validate(Map.of("type", "VISITOR")))
        .containsExactly(new FieldError("type", SubmissionValidator.CHOOSE_TYPE));
  }

  @Test
  void textAtTheLengthLimitIsAcceptedAndOneMoreIsRejected() {
    assertThat(validate(Map.of("firstName", "a".repeat(100)))).isEmpty();
    assertThat(validate(Map.of("firstName", "a".repeat(101))))
        .containsExactly(new FieldError("firstName", "Must be at most 100 characters."));
    assertThat(validate(Map.of("organization", "o".repeat(201))))
        .containsExactly(new FieldError("organization", "Must be at most 200 characters."));
  }

  @Test
  void overlongEmailIsReportedOnlyAsTooLong() {
    String email = "a".repeat(250) + "@x.si";
    assertThat(validate(Map.of("email", email)))
        .containsExactly(new FieldError("email", "Must be at most 254 characters."));
  }

  @Test
  void fieldOfTheOtherTypeIsNotAllowed() {
    assertThat(validate(Map.of("studentId", "123")))
        .containsExactly(new FieldError("studentId", SubmissionValidator.NOT_ALLOWED));
    assertThat(validate(Map.of("studentId", "   "))).isEmpty();
  }

  @Test
  void optionNotAvailableToTheTypeIsRejected() {
    Map<String, Object> v = new HashMap<>();
    v.put("type", "STUDENT");
    v.put("organization", null);
    v.put("studyInstitution", "Uni");
    v.put("studyProgramme", "CS");
    v.put("studentId", "1");
    v.put("optionIds", List.of("ext"));
    assertThat(validate(v))
        .containsExactly(new FieldError("options", "Option 'ext' is not available."));
  }

  @Test
  void inactiveOptionIsRejectedEvenWithoutAValidType() {
    List<FieldError> errors = validate(Map.of("type", "", "optionIds", List.of("off", "ext")));
    assertThat(errors)
        .contains(new FieldError("options", "Option 'off' is not available."))
        .doesNotContain(new FieldError("options", "Option 'ext' is not available."));
  }

  @Test
  void duplicateOptionIsReportedOnce() {
    assertThat(validate(Map.of("optionIds", List.of("both", "both", "both"))))
        .containsExactly(
            new FieldError("options", "Option 'both' is selected more than once."));
  }

  @Test
  void nullOptionIdIsNotAvailable() {
    List<String> ids = new ArrayList<>();
    ids.add(null);
    assertThat(validate(Map.of("optionIds", ids)))
        .containsExactly(new FieldError("options", "Option 'null' is not available."));
  }

  @Test
  void fiftyOptionsAreCheckedAndFiftyOneAreTooMany() {
    List<String> fifty = new ArrayList<>();
    for (int i = 0; i < 50; i++) {
      fifty.add("x" + i);
    }
    assertThat(validate(Map.of("optionIds", fifty))).hasSize(50);
    fifty.add("x50");
    assertThat(validate(Map.of("optionIds", fifty)))
        .containsExactly(new FieldError("options", SubmissionValidator.TOO_MANY_OPTIONS));
  }

  @Test
  void unknownConsentAndMissingMandatoryConsentAreReported() {
    assertThat(validate(Map.of("consents", Map.of("newsletter", true))))
        .containsExactlyInAnyOrder(
            new FieldError("consents.newsletter", SubmissionValidator.UNKNOWN_CONSENT),
            new FieldError("consents.privacy", SubmissionValidator.CONSENT_REQUIRED));
  }

  @Test
  void optionalConsentMayBeMissing() {
    assertThat(validate(Map.of("consents", Map.of("privacy", true, "photos", false)))).isEmpty();
  }

  @Test
  void blankTokenIsReported() {
    assertThat(validate(Map.of("recaptchaToken", " ")))
        .containsExactly(new FieldError("recaptchaToken", SubmissionValidator.TOKEN_REQUIRED));
  }

  @Test
  void normalizedReplacesNullCollectionsAndStripsText() {
    Submission s =
        new Submission(" EXTERNAL ", " a ", null, null, null, null, null, null, null, null, null)
            .normalized();
    assertThat(s.type()).isEqualTo("EXTERNAL");
    assertThat(s.firstName()).isEqualTo("a");
    assertThat(s.optionIds()).isEmpty();
    assertThat(s.consents()).isEmpty();
  }

  @Test
  void emailRule() {
    assertThat(SubmissionValidator.isEmail("a@b.si")).isTrue();
    assertThat(SubmissionValidator.isEmail("a@b")).isFalse();
    assertThat(SubmissionValidator.isEmail("a b@c.si")).isFalse();
    assertThat(SubmissionValidator.isEmail(null)).isFalse();
    assertThat(SubmissionValidator.isEmail("a".repeat(250) + "@b.si")).isFalse();
    assertThat(SubmissionValidator.isEmail("a".repeat(249) + "@b.si")).isTrue();
  }
}

package si.konferenca.registration.adapter.captcha;

import static org.assertj.core.api.Assertions.assertThat;

import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.net.ServerSocket;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * The production reCAPTCHA path against a mocked siteverify endpoint, including a rejected token
 * (DoD-P05, SR-01).
 */
class GoogleCaptchaVerifierIntegrationTest {

  private HttpServer server;
  private final AtomicReference<String> requestBody = new AtomicReference<>();
  private volatile int status = 200;
  private volatile String answer = "{\"success\": true}";

  @BeforeEach
  void startStub() throws IOException {
    server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
    server.createContext(
        "/siteverify",
        exchange -> {
          requestBody.set(
              new String(exchange.getRequestBody().readAllBytes(), StandardCharsets.UTF_8));
          byte[] body = answer.getBytes(StandardCharsets.UTF_8);
          exchange.sendResponseHeaders(status, body.length);
          try (OutputStream out = exchange.getResponseBody()) {
            out.write(body);
          }
        });
    server.start();
  }

  @AfterEach
  void stopStub() {
    server.stop(0);
  }

  private GoogleCaptchaVerifier verifier() {
    return new GoogleCaptchaVerifier(
        URI.create("http://127.0.0.1:" + server.getAddress().getPort() + "/siteverify"),
        "secret-key");
  }

  @Test
  void acceptedTokenIsVerifiedWithSecretTokenAndClientIp() {
    assertThat(verifier().verify("token value", "203.0.113.5")).isTrue();
    assertThat(requestBody.get())
        .isEqualTo("secret=secret-key&response=token+value&remoteip=203.0.113.5");
  }

  @Test
  void clientIpIsOmittedWhenUnknown() {
    assertThat(verifier().verify("t", null)).isTrue();
    assertThat(requestBody.get()).isEqualTo("secret=secret-key&response=t");
  }

  @Test
  void rejectedTokenIsRefused() {
    answer = "{\"success\": false, \"error-codes\": [\"invalid-input-response\"]}";
    assertThat(verifier().verify("bad", "203.0.113.5")).isFalse();
  }

  @Test
  void answersOtherThanABooleanSuccessAreRefused() {
    answer = "{\"success\": \"true\"}";
    assertThat(verifier().verify("t", null)).isFalse();
    answer = "{}";
    assertThat(verifier().verify("t", null)).isFalse();
    answer = "not json";
    assertThat(verifier().verify("t", null)).isFalse();
  }

  @Test
  void nonOkStatusIsRefused() {
    status = 500;
    assertThat(verifier().verify("t", null)).isFalse();
  }

  @Test
  void unreachableEndpointIsRefused() throws IOException {
    int closedPort;
    try (ServerSocket socket = new ServerSocket(0)) {
      closedPort = socket.getLocalPort();
    }
    GoogleCaptchaVerifier unreachable =
        new GoogleCaptchaVerifier(URI.create("http://127.0.0.1:" + closedPort + "/x"), "s");
    assertThat(unreachable.verify("t", null)).isFalse();
  }

  @Test
  void interruptedVerificationIsRefusedAndKeepsTheInterruptFlag() {
    Thread.currentThread().interrupt();
    try {
      assertThat(verifier().verify("t", null)).isFalse();
      assertThat(Thread.currentThread().isInterrupted()).isTrue();
    } finally {
      Thread.interrupted();
    }
  }

  @Test
  void testModeAcceptsOnlyThePassToken() {
    TestModeCaptchaVerifier testMode = new TestModeCaptchaVerifier();
    assertThat(testMode.verify("test-pass", null)).isTrue();
    assertThat(testMode.verify("test-pass ", null)).isFalse();
    assertThat(testMode.verify(null, null)).isFalse();
  }

  @Test
  void configurationChoosesTheVerifierByTestMode() {
    CaptchaConfiguration config = new CaptchaConfiguration();
    assertThat(config.captchaVerifier(true, "", URI.create("http://x")))
        .isInstanceOf(TestModeCaptchaVerifier.class);
    assertThat(config.captchaVerifier(false, "s", URI.create("http://x")))
        .isInstanceOf(GoogleCaptchaVerifier.class);
  }
}

package si.konferenca.registration.config;

import static org.assertj.core.api.Assertions.assertThatCode;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import org.junit.jupiter.api.Test;

/** SR-02: production refuses test mode, empty keys and organizer access without HTTPS. */
class ProductionSafetyCheckTest {

  @Test
  void safeProductionSettingsPass() {
    assertThatCode(() -> new ProductionSafetyCheck(false, "site", "secret", true))
        .doesNotThrowAnyException();
  }

  @Test
  void testModeIsRefused() {
    assertThatThrownBy(() -> new ProductionSafetyCheck(true, "site", "secret", true))
        .isInstanceOf(IllegalStateException.class)
        .hasMessageContaining("RECAPTCHA_TEST_MODE");
  }

  @Test
  void emptyOrMissingKeysAreRefused() {
    assertThatThrownBy(() -> new ProductionSafetyCheck(false, " ", "secret", true))
        .hasMessageContaining("RECAPTCHA_SITE_KEY");
    assertThatThrownBy(() -> new ProductionSafetyCheck(false, "site", "", true))
        .hasMessageContaining("RECAPTCHA_SECRET_KEY");
    assertThatThrownBy(() -> new ProductionSafetyCheck(false, null, "secret", true))
        .hasMessageContaining("RECAPTCHA_SITE_KEY");
    assertThatThrownBy(() -> new ProductionSafetyCheck(false, "site", null, true))
        .hasMessageContaining("RECAPTCHA_SECRET_KEY");
  }

  @Test
  void organizerAccessWithoutHttpsIsRefused() {
    assertThatThrownBy(() -> new ProductionSafetyCheck(false, "site", "secret", false))
        .hasMessageContaining("ORGANIZER_HTTPS_ONLY");
  }
}

