  void plainHttpFromARemoteClientIsRefusedBeforeAuthentication() throws Exception {
    MockHttpServletResponse response =
        run(
            new OrganizerHttpsOnlyFilter(true),
            request("GET", "/api/registrations/export", "203.0.113.10"));
