/** Spec §4: order of validation, token check, storage and emails. */
class RegisterParticipantTest {

  private static final ConferenceCatalogue CATALOGUE =
      new ConferenceCatalogue(
          List.of(
              new ConferenceOption(
                  "ws", "Workshop", OptionCategory.WORKSHOP, true, EnumSet.allOf(RegistrationType.class))),
          List.of(new ConsentDefinition("privacy", "I agree", true)));

  private final CaptchaVerifier captcha = mock(CaptchaVerifier.class);
  private final RegistrationStorage storage = mock(RegistrationStorage.class);
  private final RegistrationNotifier notifier = mock(RegistrationNotifier.class);
  private final Clock clock = Clock.fixed(Instant.parse("2026-10-13T20:15:03.123456Z"), ZoneOffset.UTC);
  private final RegisterParticipant useCase =
      new RegisterParticipant(CATALOGUE, captcha, storage, notifier, clock);

  private static Submission valid() {
    return new Submission(
        "EXTERNAL", " Ana ", "Novak", "ana@example.si", "Org", null, null, null,
        List.of("ws"), Map.of("privacy", true), "token");
  }

  @Test
  void invalidSubmissionIsRejectedWithoutTokenCheckOrStorage() {
    Submission invalid =
        new Submission("EXTERNAL", "", "Novak", "ana@example.si", "Org", null, null, null,
            List.of(), Map.of("privacy", true), "token");

    var outcome = useCase.register(invalid, "1.2.3.4");

    assertThat(outcome).isInstanceOf(Rejected.class);
    assertThat(((Rejected) outcome).errors()).containsExactly(new FieldError("firstName", "This field is required."));
    verify(captcha, never()).verify(any(), any());
    verify(storage, never()).store(any());
  }

  @Test
  void rejectedTokenIsAFieldErrorAndStoresNothing() {
    when(captcha.verify("token", "1.2.3.4")).thenReturn(false);

    var outcome = useCase.register(valid(), "1.2.3.4");

    assertThat(((Rejected) outcome).errors())
        .containsExactly(new FieldError("recaptchaToken", RegisterParticipant.CAPTCHA_REJECTED));
    verify(storage, never()).store(any());
    verify(notifier, never()).sendConfirmation(any());
  }

  @Test
  void acceptedRegistrationIsStoredThenMailed() {
    when(captcha.verify("token", "1.2.3.4")).thenReturn(true);
    byte[] copy = {1, 2};
    when(storage.store(any())).thenReturn(copy);

    var outcome = useCase.register(valid(), "1.2.3.4");

    Registration r = ((Accepted) outcome).registration();
    assertThat(r.firstName()).isEqualTo("Ana");
    assertThat(r.registeredAt()).isEqualTo(Instant.parse("2026-10-13T20:15:03.123Z"));
    verify(storage).store(r);
    verify(notifier).sendConfirmation(r);
    verify(notifier).notifyOrganizers(r, copy);
  }

  @Test
  void mailFailuresDoNotChangeTheOutcome() {
    when(captcha.verify(any(), any())).thenReturn(true);
    when(storage.store(any())).thenReturn(new byte[0]);
    doThrow(new IllegalStateException("smtp down")).when(notifier).sendConfirmation(any());
    doThrow(new IllegalStateException("smtp down")).when(notifier).notifyOrganizers(any(), any());

    assertThat(useCase.register(valid(), null)).isInstanceOf(Accepted.class);
    verify(notifier).notifyOrganizers(any(), any());
  }

  @Test
  void storageWritesRowThenCopyAndDeletesTheCopyUnlessCommitted() {
    RegistrationStore store = mock(RegistrationStore.class);
    JsonCopyStore copies = mock(JsonCopyStore.class);
    Registration r = TestRegistrations.external();
    when(copies.write(r)).thenReturn(new byte[] {7});
    TransactionSynchronizationManager.initSynchronization();
    try {
      assertThat(new RegistrationStorage(store, copies).store(r)).containsExactly(7);
      verify(store).save(r);
      List<TransactionSynchronization> callbacks =
          TransactionSynchronizationManager.getSynchronizations();
      assertThat(callbacks).hasSize(1);

      callbacks.get(0).afterCompletion(TransactionSynchronization.STATUS_COMMITTED);
      verify(copies, never()).delete(any());
      callbacks.get(0).afterCompletion(TransactionSynchronization.STATUS_ROLLED_BACK);
      verify(copies).delete(r.id());
    } finally {
      TransactionSynchronizationManager.clearSynchronization();
    }
  }

  @Test
  void exportWritesEveryStoredRegistration() {
    RegistrationStore store = mock(RegistrationStore.class);
    WorkbookWriter writer = mock(WorkbookWriter.class);
    List<Registration> all = List.of(TestRegistrations.external());
    when(store.findAllOldestFirst()).thenReturn(all);
    when(writer.write(all)).thenReturn(new byte[] {9});

    assertThat(new ExportRegistrations(store, writer).export()).containsExactly(9);
  }

  @Test
  void formConfigurationHidesTheSiteKeyInTestMode() {
    var real = new GetFormConfiguration(CATALOGUE, new FormSettings("C", false, "site")).get();
    assertThat(real.siteKey()).isEqualTo("site");
    assertThat(real.captchaTestMode()).isFalse();
    assertThat(real.activeOptions()).hasSize(1);
    var test = new GetFormConfiguration(CATALOGUE, new FormSettings("C", true, "site")).get();
    assertThat(test.siteKey()).isNull();
    assertThat(test.conferenceName()).isEqualTo("C");
    assertThat(test.consents()).hasSize(1);
  }

  @Test
  void storageFailureCarriesItsCause() {
    var cause = new java.io.IOException("x");
    var failure = new StorageFailedException("m", cause);
    assertThat(failure).hasMessage("m").hasCause(cause);
    ArgumentCaptor<Registration> unused = ArgumentCaptor.forClass(Registration.class);
    assertThat(unused).isNotNull();
  }
}

package si.konferenca.registration.domain;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.time.Instant;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import org.junit.jupiter.api.Test;

/** The accepted registration and the catalogue (BR-01, BR-04, BR-05, SB-14). */
class RegistrationTest {

  private static final ConferenceCatalogue CATALOGUE =
      new ConferenceCatalogue(
          List.of(
              new ConferenceOption(
                  "ws", "Workshop", OptionCategory.WORKSHOP, true, EnumSet.allOf(RegistrationType.class)),
              new ConferenceOption(
                  "ot", "Tour", OptionCategory.OTHER, true, EnumSet.of(RegistrationType.STUDENT))),
          List.of(
              new ConsentDefinition("privacy", "I agree", true),
              new ConsentDefinition("photos", "Photos ok", false)));

  private static final Instant AT = Instant.parse("2026-10-13T20:15:03Z");

  @Test
  void studentRegistrationKeepsOnlyStudentFieldsAndGivenConsents() {
    Submission s =
        new Submission(
            "STUDENT", "Luka", "Kranjc", "l@x.si", "ignored", "Uni", "CS", "63",
            List.of("ot", "ws"), Map.of("privacy", true, "photos", false), "t");
    UUID id = UUID.randomUUID();

    Registration r = Registration.accept(s, CATALOGUE, id, AT);

    assertThat(r.id()).isEqualTo(id);
    assertThat(r.type()).isEqualTo(RegistrationType.STUDENT);
    assertThat(r.organization()).isNull();
    assertThat(r.studyInstitution()).isEqualTo("Uni");
    assertThat(r.studyProgramme()).isEqualTo("CS");
    assertThat(r.studentId()).isEqualTo("63");
    assertThat(r.options())
        .containsExactly(
            new Registration.SelectedOption("ot", "Tour", OptionCategory.OTHER),
            new Registration.SelectedOption("ws", "Workshop", OptionCategory.WORKSHOP));
    assertThat(r.consents()).containsExactly(new Registration.GivenConsent("privacy", "I agree", AT));
  }

  @Test
  void externalRegistrationKeepsOnlyTheOrganization() {
    Submission s =
        new Submission(
            "EXTERNAL", "Ana", "Novak", "a@x.si", "Org", "Uni", "CS", "63",
            List.of(), Map.of("privacy", true, "photos", true), "t");

    Registration r = Registration.accept(s, CATALOGUE, UUID.randomUUID(), AT);

    assertThat(r.organization()).isEqualTo("Org");
    assertThat(r.studyInstitution()).isNull();
    assertThat(r.studyProgramme()).isNull();
    assertThat(r.studentId()).isNull();
    assertThat(r.consents()).extracting(Registration.GivenConsent::id).containsExactly("privacy", "photos");
  }

  @Test
  void timesAreFormattedInUtcWithMilliseconds() {
    assertThat(Registration.format(AT)).isEqualTo("2026-10-13T20:15:03.000Z");
    assertThat(Registration.format(Instant.parse("2026-01-02T03:04:05.678Z")))
        .isEqualTo("2026-01-02T03:04:05.678Z");
  }

  @Test
  void catalogueRejectsDuplicateConsentsAndFindsEntries() {
    assertThatThrownBy(
            () ->
                new ConferenceCatalogue(
                    List.of(),
                    List.of(new ConsentDefinition("p", "a", true), new ConsentDefinition("p", "b", false))))
        .isInstanceOf(InvalidConfigurationException.class)
        .hasMessage("Duplicate consent id 'p'");
    assertThat(CATALOGUE.option("ws")).isPresent();
    assertThat(CATALOGUE.option("none")).isEmpty();
  }

  @Test
  void optionsAreSelectableOnlyWhenActiveAndAvailable() {
    ConferenceOption inactive =
        new ConferenceOption("x", "X", OptionCategory.MEAL, false, EnumSet.allOf(RegistrationType.class));
    assertThat(inactive.selectableBy(RegistrationType.EXTERNAL)).isFalse();
    assertThat(CATALOGUE.option("ot").orElseThrow().selectableBy(RegistrationType.EXTERNAL)).isFalse();
    assertThat(CATALOGUE.option("ot").orElseThrow().selectableBy(RegistrationType.STUDENT)).isTrue();
  }

  @Test
  void enumsParseExactNamesAndCarryLabels() {
    assertThat(RegistrationType.parse("STUDENT")).contains(RegistrationType.STUDENT);
    assertThat(RegistrationType.parse("student")).isEmpty();
    assertThat(RegistrationType.parse(null)).isEmpty();
    assertThat(RegistrationType.EXTERNAL.label()).isEqualTo("External participant");
    assertThat(RegistrationType.STUDENT.label()).isEqualTo("Student");
    assertThat(OptionCategory.parse("MEAL")).contains(OptionCategory.MEAL);
    assertThat(OptionCategory.parse("meal")).isEmpty();
    assertThat(OptionCategory.OTHER.singular()).isEqualTo("Other activity");
    assertThat(OptionCategory.OTHER.plural()).isEqualTo("Other activities");
    assertThat(OptionCategory.WORKSHOP.singular()).isEqualTo("Workshop");
    assertThat(OptionCategory.EVENT.plural()).isEqualTo("Events");
  }

  @Test
  void configurationErrorKeepsItsCause() {
    var cause = new IllegalStateException("x");
    assertThat(new InvalidConfigurationException("m", cause)).hasMessage("m").hasCause(cause);
  }
}

