  @ArchTest
  static final ArchRule domainDependsOnNoOtherLayerOrFramework =
      noClasses()
          .that()
          .resideInAPackage(ROOT + ".domain..")
          .should()
          .dependOnClassesThat()
          .resideInAnyPackage(
